    /**
     * Method to retrieve the Claim via ClaimFetchOneSummary
     * @param 	summary ClaimFetchOneSummary 
     * @return 	ClaimFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Claim getClaim( ClaimFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ClaimFetchOneSummary arg cannot be null" );
    	
    	Claim entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Claim
        	// --------------------------------------
        	CompletableFuture<Claim> futureEntity = queryGateway.query(new FindClaimQuery( new LoadClaimFilter( summary.getClaimId() ) ), ResponseTypes.instanceOf(Claim.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Claim with id " + summary.getClaimId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


